function reportData(id){const c=course(id),classes=db.classes.filter(t=>t.courseId===c.id),enrollments=db.enrollments.filter(e=>classes.some(t=>t.id===e.classId)),active=enrollments.filter(e=>e.status==='Inscrito');return {curso:c.name,turmas:classes.length,inscricoes:active.length,canceladas:enrollments.length-active.length,conclusoes:active.filter(e=>completion(e.personId,e.classId)).length,materiaisInstitucionais:db.materials.filter(m=>m.courseId===c.id&&m.origin==='Institucional'&&m.status==='Aprovado').length,materiaisTradicionais:db.materials.filter(m=>m.courseId===c.id&&m.origin==='Tradicional'&&m.status==='Aprovado').length};}
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function handle(action,el){if(action==='go-consents'){navigate('consents');return;}if(!canAction(action)){toast('Ação não permitida para o perfil demonstrativo.');return;}const id=Number(el.dataset.id);switch(action){case 'self-enroll':{const c=classroom(id);if(role!=='participante'||!c||course(c.courseId)?.status!=='Ativo')return toast('Turma indisponível.');if(course(c.courseId)?.autoEnrollment===false)return toast('Esta formação não permite autoinscrição.');if(countEnrolled(id)>=c.capacity)return toast('Sem vagas.');if(enrolled(demoPersonId,id))return toast('Inscrição já existente.');if(!prerequisitesMet(demoPersonId,c.courseId))return toast('Pré-requisitos ainda não concluídos.');db.enrollments.push({id:nextId('enrollments'),personId:demoPersonId,classId:id,status:'Inscrito'});record('Autoinscrição','Inscrição demonstrativa realizada.');notify('Nova inscrição','Inscrição de participante registrada.');navigate('enrollments');break;}case 'new-course':formCourse();break;case 'edit-course':formCourse(id);break;case 'go-courses':navigate('courses');break;case 'go-materials':navigate('materials');break;case 'course-detail':navigate('course-detail',id);break;case 'set-course-status':{const c=course(id),s=el.dataset.status;if(!c||!({'Rascunho':['Em revisão'],'Em revisão':['Rascunho','Ativo'],'Ativo':['Encerrado'],'Encerrado':[]}[c.status]||[]).includes(s))return toast('Transição de curso não permitida.');if(c.status==='Em revisão'&&s==='Ativo'&&!confirm('Confirmar aprovação e ativação deste curso na demonstração?'))break;c.status=s;record('Curso',`Situação alterada para ${s}.`);navigate('course-detail',id);break;}case 'new-trail':formTrail();break;case 'new-material':formMaterial();break;case 'new-consent':formConsent();break;case 'new-class':formClass();break;case 'new-meeting':formMeeting(id);break;case 'new-enrollment':formEnrollment();break;case 'new-attendance':formAttendance();break;case 'edit-attendance':formAttendance(id);break;case 'new-assessment':formAssessment();break;case 'edit-assessment':formAssessment(id);break;case 'cancel-enrollment':{const e=get('enrollments',id);if(!e||role!=='gestor')return toast('O cancelamento efetivo é responsabilidade do Gestor pedagógico.');if(confirm('Cancelar inscrição? O histórico será mantido.')){e.status='Cancelado';record('Inscrição','Inscrição cancelada; vaga liberada.');navigate('enrollments');}break;}case 'review-material':{const m=get('materials',id);openModal('Analisar material','Aprovação exige consentimento vigente para conteúdos tradicionais.',select('decision','Decisão',['Aprovado','Devolvido ao autor'])+area('reason','Justificativa'),f=>{if(m.origin==='Tradicional'&&!db.consents.some(c=>c.id===m.consentId&&c.status==='Vigente')&&f.decision==='Aprovado')throw Error('É necessário consentimento comunitário vigente.');if(f.decision==='Devolvido ao autor'&&!f.reason.trim())throw Error('Informe a justificativa obrigatória para devolução.');m.status=f.decision;m.reason=f.reason;record('Material',`Material ${f.decision.toLowerCase()}.`);notify('Decisão sobre material',`${m.title}: ${f.decision}`);navigate('materials');});break;}case 'revoke-consent':{const c=get('consents',id);if(!c||get('materials',c.materialId)?.community!==demoLeadershipCommunity)return toast('Consentimento fora da comunidade representada.');if(confirm('Revogar este consentimento?')){c.status='Revogado';const m=get('materials',c.materialId);if(m){m.status='Revogado';m.version++;}record('Consentimento','Consentimento revogado. Acesso demonstrativo ao material bloqueado.');navigate('consents');}break;}case 'download-material':{const m=get('materials',id);if(!m||m.status!=='Aprovado'||(m.origin==='Tradicional'&&!db.consents.some(c=>c.id===m.consentId&&c.status==='Vigente')))return toast('Material não disponível ou sem consentimento vigente.');toast('Download ilustrativo: nenhum arquivo foi armazenado no dispositivo.');break;}case 'show-certificate':{const e=get('enrollments',id);if(!e||(role==='participante'&&e.personId!==demoPersonId)||!completion(e.personId,e.classId))return toast('Certificado indisponível para este perfil.');const c=classroom(e.classId),courseObj=course(c.courseId);openModal('Certificado demonstrativo','Prévia sem validade institucional.',`<div class="info-box"><h3>${escapeHTML(fullName(e.personId))}</h3><p>Concluiu ${escapeHTML(courseObj.name)} · ${courseObj.hours} horas</p><p>Território: ${escapeHTML(courseObj.territories)}</p><p>Código demonstrativo: ${certificateCode(e.personId,e.classId)}</p></div>`,()=>{},'Fechar','CERTIFICADO');$('#modalSubmit').type='button';$('#modalSubmit').onclick=closeModal;break;}case 'read-notification':get('notifications',id).read=true;render();break;case 'toggle-connection':online=!online;render();break;case 'sync-now':if(!online)toast('Sem conexão simulada. Ative a conexão para sincronizar.');else{db.syncQueue.forEach(q=>q.status='Sincronizado (simulado)');toast('Fila marcada como sincronizada nesta sessão.');render();}break;case 'preview-report':case 'export-csv':case 'print-report':{const selected=Number($('#reportCourse')?.value);if(!selected)return toast('Selecione um curso.');const data=reportData(selected);$('#reportPreview').innerHTML=Object.entries(data).map(([k,v])=>`<p><strong>${escapeHTML(k)}:</strong> ${escapeHTML(v)}</p>`).join('');if(action==='export-csv')download('\ufeff'+Object.entries(data).map(([k,v])=>`"${String(k).replace(/"/g,'""')}";"${String(v).replace(/"/g,'""')}"`).join('\r\n'),'relatorio-sistid-demo.csv','text/csv;charset=utf-8');if(action==='print-report')window.print();break;}default:toast('Esta ação não está disponível nesta demonstração.');}}
document.addEventListener('click',e=>{const switcher=e.target.closest('[data-role]');if(switcher){setRole(switcher.dataset.role);return;}if(e.target.closest('#profileButton')){const m=$('#profileMenu');m.hidden=!m.hidden;$('#profileButton').setAttribute('aria-expanded',String(!m.hidden));return;}if(!e.target.closest('#profileSwitcher')){$('#profileMenu').hidden=true;$('#profileButton').setAttribute('aria-expanded','false');}const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}const action=e.target.closest('[data-action]');if(action){handle(action.dataset.action,action);return;}const parent=e.target.closest('[data-submenu]');if(parent){const menu=$(`#submenu-${parent.dataset.submenu}`),open=parent.getAttribute('aria-expanded')==='true';parent.setAttribute('aria-expanded',String(!open));parent.classList.toggle('is-open',!open);menu.hidden=open;return;}if(e.target.closest('[data-external-module]'))toast('Este módulo externo não está implementado no protótipo de Formação.');if(e.target.closest('[data-filter]')){filter=e.target.closest('[data-filter]').dataset.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));$('#coursesGrid').innerHTML=courseCards();}});
$('#dynamicForm').addEventListener('submit',e=>{e.preventDefault();if(!modalHandler)return;const f=Object.fromEntries(new FormData(e.currentTarget));try{modalHandler(f);closeModal();$('#modalSubmit').type='submit';$('#modalSubmit').onclick=null;}catch(err){toast(err.message||'Não foi possível concluir a operação.');}});
$('#modalClose').addEventListener('click',closeModal);$('#cancelModal').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#modalBackdrop').hidden)closeModal();else{closeSidebar();$('#profileMenu').hidden=true;$('#profileButton').setAttribute('aria-expanded','false');}}});window.addEventListener('resize',syncSidebar);document.addEventListener('change',e=>{if(e.target.id==='themeSwitch'&&role==='administrador'){darkMode=e.target.checked;try{localStorage.setItem('sistid-dark-mode',String(darkMode));}catch(_){}applyTheme();}});$('#menuToggle').addEventListener('click',openSidebar);$('#sidebarScrim').addEventListener('click',closeSidebar);window.addEventListener('message',e=>{if(e.source!==$('#sidebarFrame')?.contentWindow||e.data?.source!=='sistid-sidebar')return;if(e.data.type==='ready')syncSidebar();else if(e.data.type==='navigate')navigate(e.data.view);else if(e.data.type==='close')closeSidebar();else if(e.data.type==='external')toast('O módulo externo pertence a outra área e não é implementado nesta demonstração.');});$('#notificationBtn').addEventListener('click',()=>navigate('notifications'));
